  "Net-S" = "#6A3D9A", "Orlin" = "#B07AA1",
  "Hungarian" = "#D55E00", "Munkres" = "#8C3B00", "Ramshaw" = "#5A4634",
  "HK-01" = "#117733", "Brute-F" = "#999933"
)

# Curves run from the lower left to the upper right on log-log axes, so the
