key_order <- list(
  "JV / augmenting path" = c("JV", "SAP", "LAPMOD"),
  "Auction"              = c("Auction", "Auction-GS", "Auction-S"),
  "Cost scaling"         = c("CSA", "Gabow-T", "SSAP-B"),
