                             "Brute-F")
)
lt_pool <- c("solid", "22", "12", "4212", "62")
lt <- unlist(lapply(key_order, function(v) setNames(lt_pool[seq_along(v)], v)))
names(lt) <- unlist(key_order)

key <- do.call(rbind, lapply(names(key_order), function(p) {
  data.frame(panel = factor(p, levels = panel_levels),
             label = key_order[[p]],
             k = seq_along(key_order[[p]]) - 1,
             stringsAsFactors = FALSE)
}))
x_lim <- c(3.5, 6000)
y_lim <- c(0.008, 2e5)
lx <- log10(x_lim); ly <- log10(y_lim)
key$x    <- 10^(lx[1] + 0.05 * diff(lx))
key$xend <- 10^(lx[1] + 0.17 * diff(lx))
key$y    <- 10^(ly[2] - (0.05 + 0.085 * key$k) * diff(ly))

